type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    let len = a.len();

    assert!(r > 0 && c > 0, "Shape dimensions must be positive");
    assert!(shape.len() == 2, "Shape must have exactly two elements");
    assert!(len > 0, "Input array must have positive length");
    assert!(len == r || len == c, "Array length must match one dimension of shape");

    let mut result = Vec::with_capacity(r);

    if len == r {
        // Treat `a` as a column vector: broadcast each element across the row
        for &val in &a {
            let row = vec![val; c];
            result.push(row);
        }
    } else {
        // Treat `a` as a row vector: duplicate the entire row `r` times
        for _ in 0..r {
            result.push(a.clone());
        }
    }

    result
}